// What a partner plan still needs before it can be saved, in the partner's words; the same limits as the server (service-plan/plan.routes planBody).
export const PLAN_LIMITS = { nameMin: 3, itemsMax: 10, visitsMin: 1, visitsMax: 31, discountMax: 40, pausesMax: 10, priceMinPaise: 100, priceMaxPaise: 50000000 };

export function planProblems({ type, name, itemCount, pricePaise, visitsPerMonth, d3, d5, pauses }) {
  const L = PLAN_LIMITS;
  const out = [];
  if (String(name || '').trim().length < L.nameMin) out.push(`Give the plan a name (at least ${L.nameMin} letters)`);
  if (!itemCount) out.push('Tap at least one job below to put it in the plan');
  if (itemCount > L.itemsMax) out.push(`A plan can hold up to ${L.itemsMax} jobs`);
  if (!pricePaise || pricePaise < L.priceMinPaise) out.push('Set the price');
  if (pricePaise > L.priceMaxPaise) out.push('The price can be up to ₹5,00,000');
  if (type === 'monthly') {
    const v = Number(visitsPerMonth);
    if (!v || v < L.visitsMin || v > L.visitsMax) out.push(`Visits a month must be from ${L.visitsMin} to ${L.visitsMax}`);
    if (Number(d3) > L.discountMax || Number(d5) > L.discountMax) out.push(`A discount can be up to ${L.discountMax}%`);
    if (Number(pauses) > L.pausesMax) out.push(`Pause days can be up to ${L.pausesMax} a month`);
  }
  return out;
}
